Hub.ClearAllESP = function(self)
	for _, h in pairs(self.ESP.Highlights) do
		if h then
			pcall(function()
				h:Destroy();
			end);
		end
	end
	table.clear(self.ESP.Highlights);
	for _, d in pairs(self.ESP.Drawings) do
		if d.Box then
			pcall(function()
				d.Box.Visible = false;
				d.Box:Remove();
			end);
		end
		if d.Tracer then
			pcall(function()
				d.Tracer.Visible = false;
				d.Tracer:Remove();
			end);
		end
	end
	table.clear(self.ESP.Drawings);
	for _, p in ipairs(self.Services.Players:GetPlayers()) do
		local char = p.Character;
		if char then
			local bg = char:FindFirstChild("MM2_ESP_Top");
			if bg then
				bg:Destroy();
			end
			local bgBot = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\113\127\219\120\121\97\185\120\126\93\157", "\39\60\50\233"));
			if bgBot then
				bgBot:Destroy();
			end
		end
	end
	self:ClearGunESP();
end;
