Hub.ApplyPotatoOptimizer = function(self, enabled)
	local lighting = self.Services.Lighting;
	if not self.State.PotatoBackup then
		self.State.PotatoBackup = {};
	end
	if enabled then
		if not self.State.PotatoLightingBackup then
			self.State.PotatoLightingBackup = {GlobalShadows=lighting.GlobalShadows,FogEnd=lighting.FogEnd,[LUAOBFUSACTOR_DECRYPT_STR_0("\88\159\49\91\114\153\54\89\105\158", "\60\26\237\88")]=lighting.Brightness};
		end
		pcall(function()
			lighting.GlobalShadows = false;
			lighting.FogEnd = 8999999488;
			lighting.Brightness = 2;
		end);
		for _, obj in ipairs(self.Services.Workspace:GetDescendants()) do
			self:OptimizeInstance(obj);
		end
		if not self.State.OptimizerConn then
			self.State.OptimizerConn = self.Services.Workspace.DescendantAdded:Connect(function(obj)
				if self.Config.Toggles.PotatoOptimizer then
					self:OptimizeInstance(obj);
				end
			end);
		end
	else
		if self.State.PotatoLightingBackup then
			pcall(function()
				lighting.GlobalShadows = self.State.PotatoLightingBackup.GlobalShadows;
				lighting.FogEnd = self.State.PotatoLightingBackup.FogEnd;
				lighting.Brightness = self.State.PotatoLightingBackup.Brightness;
			end);
			self.State.PotatoLightingBackup = nil;
		else
			pcall(function()
				lighting.GlobalShadows = self.Config.Toggles.WorldShadows;
				lighting.FogEnd = (self.Config.Toggles.NoFog and 8999999488) or 500;
			end);
		end
		if self.State.OptimizerConn then
			self.State.OptimizerConn:Disconnect();
			self.State.OptimizerConn = nil;
		end
		for obj, data in pairs(self.State.PotatoBackup) do
			if (obj and obj.Parent) then
				pcall(function()
					if (data.Type == "BasePart") then
						obj.Material = data.Material;
						obj.CastShadow = data.CastShadow;
						obj.Reflectance = data.Reflectance;
						if (data.TextureID and obj:IsA("MeshPart")) then
							obj.TextureID = data.TextureID;
						end
					elseif (data.Type == "Decal") then
						obj.Transparency = data.Transparency;
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\235\58\113\229\167\217\38\89\227\189\208", "\206\184\74\20\134")) then
						obj.TextureId = data.TextureId;
					elseif (data.Type == LUAOBFUSACTOR_DECRYPT_STR_0("\12\235\233\182\255\79\57\206\52\225", "\172\88\132\142\209\147\42\88")) then
						obj.Enabled = data.Enabled;
					end
				end);
			end
		end
		table.clear(self.State.PotatoBackup);
	end
end;
Hub.OptimizeInstance = function(self, obj)
	pcall(function()
		if not self.State.PotatoBackup then
			self.State.PotatoBackup = {};
		end
		if obj:IsA("BasePart") then
			local isPlayerChar = obj.Parent and obj.Parent:FindFirstChildOfClass("Humanoid");
			if not isPlayerChar then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {Type="BasePart",Material=obj.Material,CastShadow=obj.CastShadow,Reflectance=obj.Reflectance,TextureID=((obj:IsA("MeshPart") and obj.TextureID) or nil)};
				end
				obj.Material = Enum.Material.SmoothPlastic;
				obj.CastShadow = false;
				obj.Reflectance = 0;
				if obj:IsA("MeshPart") then
					local nm = obj.Name:lower();
					local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
					if (nm:find("coin") or pnm:find(LUAOBFUSACTOR_DECRYPT_STR_0("\132\133\197\3", "\222\231\234\172\109\86\149"))) then
						obj.TextureID = "";
					end
				end
			end
		elseif obj:IsA("SpecialMesh") then
			local pnm = (obj.Parent and obj.Parent.Name:lower()) or "";
			local ppnm = (obj.Parent and obj.Parent.Parent and obj.Parent.Parent.Name:lower()) or "";
			if (pnm:find(LUAOBFUSACTOR_DECRYPT_STR_0("\238\224\201\22", "\120\141\143\160")) or ppnm:find("coin")) then
				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {[LUAOBFUSACTOR_DECRYPT_STR_0("\116\181\166\87", "\50\32\204\214")]="SpecialMesh",[LUAOBFUSACTOR_DECRYPT_STR_0("\178\66\45\109\166\3\131\110\49", "\113\230\39\85\25\211")]=obj.TextureId};
				end
				obj.TextureId = "";
			end
		elseif (obj:IsA("Decal") or obj:IsA("Texture")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Decal",Transparency=obj.Transparency};
			end
			obj.Transparency = 1;
		elseif (obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\238\186\20\252\46\200\167\78\251\182\15\252\51\206\185", "\43\190\219\102\136\71\171\203")) or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") or obj:IsA("Light")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Toggleable",Enabled=obj.Enabled};
			end
			obj.Enabled = false;
		end
	end);
end;
Hub.SetFarmNoClip = function(self, on)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if on then
		if not char then
			return;
		end
		if hum then
			pcall(function()
				hum.PlatformStand = true;
			end);
		end
		for _, p in ipairs(char:GetDescendants()) do
			if (p:IsA("BasePart") and p.CanCollide) then
				if (self.AutoFarm.NoClipCache[p] == nil) then
					self.AutoFarm.NoClipCache[p] = p.CanCollide;
				end
				p.CanCollide = false;
			end
		end
	else
		if hum then
			hum.PlatformStand = false;
			hum:ChangeState(Enum.HumanoidStateType.GettingUp);
		end
		for p, v in pairs(self.AutoFarm.NoClipCache or {}) do
			if (p and p.Parent) then
				pcall(function()
					p.CanCollide = v;
				end);
			end
		end
		self.AutoFarm.NoClipCache = {};
	end
end;
Hub.ReturnToSurface = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if not root then
		return;
	end
	local upParams = RaycastParams.new();
	upParams.FilterType = Enum.RaycastFilterType.Exclude;
	upParams.IgnoreWater = true;
	upParams.FilterDescendantsInstances = {char};
	local res = self.Services.Workspace:Raycast(root.Position, Vector3.new(0, 400, 0), upParams);
	local y = (res and (res.Position.Y + 5)) or (self.AutoFarm.DownRefY and (self.AutoFarm.DownRefY + 5)) or nil;
	if y then
		pcall(function()
			root.CFrame = CFrame.new(root.Position.X, y, root.Position.Z);
			root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
			root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
		end);
	end
end;
Hub.ReleaseFarm = function(self)
	if self.AutoFarm.WasDown then
		self.AutoFarm.WasDown = false;
		self:ReturnToSurface();
	end
	self:SetFarmNoClip(false);
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if root then
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end
end;
Hub.StopAutoFarm = function(self)
	self.AutoFarm.Target = nil;
	self:ReleaseFarm();
end;
Hub.StopAutoFarmTween = function(self)
	self:StopAutoFarm();
end;
