	local cf = CFrame.new(np);
	if (mode == "Down") then
		cf = cf * CFrame.Angles(-math.pi * 0.5, 0, 0);
		self.AutoFarm.WasDown = true;
	end
	pcall(function()
		root.CFrame = cf;
		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
	end);
