Hub.UnequipSkin = function(self, slot)
	self.SkinSystem.Picked[slot] = nil;
	if (slot == "Knife") then
		self.SkinSystem.CurrentKnife = "None";
	else
		self.SkinSystem.CurrentGun = "None";
	end
	local tool = self:FindToolBySlot(slot);
	local display = self:FindDisplayPedestal(slot);
	if tool then
		self:ClearSkinGarbage(tool);
	end
	if display then
		self:ClearSkinGarbage(display);
	end
	for inst, data in pairs(self.SkinSystem.Saved) do
		if (inst and inst.Parent) then
			if data.grip then
				pcall(function()
					inst.Grip = data.grip;
				end);
			end
			if data.size then
				pcall(function()
					inst.Size = data.size;
				end);
			end
			if data.trans then
				pcall(function()
					inst.Transparency = data.trans;
				end);
			end
			if data.mod then
				pcall(function()
					inst.LocalTransparencyModifier = data.mod;
				end);
			end
			if data.volume then
				pcall(function()
					inst.Volume = data.volume;
