	for _, anim in ipairs(self.Animations.List) do
		local matchesTab = ((tab == "Favorites") and self.Animations.Favorites[anim.Id]) or (anim.Category == tab);
		local matchesSearch = (q == "") or (anim.Name:lower():find(q) ~= nil);
